from core import *

@register('limits','padic-digit-extrema','factorial-valuations-digit-extrema','Legendre-digit-counting-and-extremal-subsequences','A factorial valuation hides a digit sum; bounding digits is insufficient without constructing a subsequence that asymptotically fills every digit.','The gcd-density construction averages coprimality. This problem controls extremal base-digit behavior of a single sequence.',[{'caseId':'prime-'+str(p),'p':p,'purpose':'A prime radix with a distinct maximum digit and exact valuation law.'} for p in [2,3,5,7,11,13,17,19]],['prime valuations','base expansions','limsup'])
def padic(case):
 p=s.Integer(case['p']);A=p-1
 def valuation(N):
  total=0
  while N: N//=int(p);total+=N
  return total
 for N in [1,int(p)-1,int(p),int(p*p)-1,int(p*p),int(p**3)-1]:
  q=N;digits=0
  while q:digits+=q%int(p);q//=int(p)
  ck('Legendre factorial difference at a boundary digit pattern '+str(N),valuation(int(p)*N)-int(p)*valuation(N),digits)
 analytic('Legendre formula and extremal digit subsequences',['The displayed radix is prime; the limit index is a positive integer tending to infinity.'],['Counting multiples of successive prime powers gives v_p(N!)=(N-s_p(N))/(p-1). Multiplication by p shifts digits, so v_p((pN)!)-p v_p(N!)=s_p(N).','If p^j<=N<p^(j+1), then s_p(N)<= (p-1)(j+1); dividing by log_p N gives limsup at most p-1.','For N=p^j-1 all j digits equal p-1. The quotient tends to p-1 and proves sharpness.'])
 return candidate(T('For a prime p, let the exponent of p in an integer be denoted by ')+r'v_p.'+r'\quad p='+L(p)+r'.\quad\limsup_{n\to\infty}\frac{v_p(('+L(p)+r'n)!)-'+L(p)+r'v_p(n!)}{\log_{'+L(p)+r'}n}',A,[(p,'Count the number of possible digit values instead of the largest digit'),(p+1,'Include a spurious leading carry'),(p/(p-1),'Use the geometric sum in Legendre formula without the digit cancellation'),(1/(p-1),'Invert the maximal digit contribution'),(s.Integer(0),'Inspect only indices that are exact powers of the radix'),((p-1)/2,'Substitute a typical digit average for an extremal subsequence'),(2*(p-1),'Count both factorial valuations without cancellation')],[T('Count prime powers in a factorial, then rewrite that count using the base expansion.'),r's_p(n)=\textnormal{the sum of the base-}p\textnormal{ digits of }n',r'v_p(n!)=\frac{n-s_p(n)}{p-1},\quad s_p(pn)=s_p(n),\quad v_p((pn)!)-pv_p(n!)=s_p(n)',r'p^j\le n<p^{j+1}\quad\Longrightarrow\quad s_p(n)\le(p-1)(j+1)',r'\limsup_{n\to\infty}\frac{s_p(n)}{\log_p n}\le p-1',r'n=p^j-1:\quad s_p(n)=(p-1)j,\quad\frac{(p-1)j}{\log_p(p^j-1)}\longrightarrow p-1',r'p='+L(p)+r'\quad\Longrightarrow\quad\textnormal{the limsup is }'+L(A)],'factorial-valuations-to-extremal-digit-sum')

@register('limits','pell-liminf','quadratic-diophantine-best-approximation','integer-norm-lower-bound-and-Pell-subsequence','An integer norm proves a universal asymptotic lower bound, while an infinite Pell orbit supplies the matching exceptional subsequence.','Average equidistribution cannot determine the best individual rational approximations.',[{'caseId':'radicand-'+str(d),'d':d,'purpose':'A nonsquare radicand with its own exact Pell orbit.'} for d in [2,3,5,6,7,10,11,13]],['nearest integer distance','liminf','Pell equation'])
def pell(case):
 d=s.Integer(case['d']);q=1
 while True:
  p=math.isqrt(1+int(d)*q*q)
  if p*p-int(d)*q*q==1:break
  q+=1
 P,Q=s.symbols('P Q',integer=True);A=1/(2*s.sqrt(d))
 ck('The explicit seed has positive Pell norm',p*p-d*q*q,1)
 ck('Multiplication by the seed preserves the integer norm',(p*P+d*q*Q)**2-d*(q*P+p*Q)**2,(P*P-d*Q*Q))
 analytic('Integer norm bound with an attaining Pell orbit',['The radicand is a positive nonsquare integer; nearest-integer distance is defined explicitly.'],['For a nearest integer p to n sqrt(d), p^2-d n^2 is a nonzero integer. Thus n|p-n sqrt(d)|>=1/(p/n+sqrt(d)), and p/n tends to sqrt(d).','Powers of the displayed positive Pell unit give integer pairs with norm one and denominators tending to infinity. Their positive errors equal 1/(p+n sqrt(d)) and are eventually less than one half, so they are nearest-integer errors.','The normalized errors along that subsequence tend exactly to 1/(2sqrt(d)).'])
 return candidate(r'\|x\|=\min_{j\in\mathbb Z}|x-j|.\qquad\liminf_{n\to\infty}n\|n\sqrt{'+L(d)+r'}\|',A,[(1/s.sqrt(d),'Omit the second conjugate contribution'),(1/(2*d*s.sqrt(d)),'Normalize by the radicand once again'),(1/(4*s.sqrt(d)),'Apply the conjugate factor two twice'),(s.sqrt(d),'Lose the conjugate factor and invert the radicand normalization'),(s.sqrt(d)/2,'Invert the rational-approximation normalization'),(2/s.sqrt(d),'Invert the conjugate factor two')],[T('Let p be an integer nearest to n times the displayed square root. A nonzero integer norm gives a lower bound for every approximation.'),r'|p^2-'+L(d)+r'n^2|\ge1\quad\Longrightarrow\quad n|p-n\sqrt{'+L(d)+r'}|\ge\frac1{p/n+\sqrt{'+L(d)+r'}}',T('For a nearest integer, its ratio to the denominator tends to the displayed square root.'),r'\liminf_{n\to\infty}n\|n\sqrt{'+L(d)+r'}\|\ge'+L(A),r''+str(p)+r'^2-'+L(d)+r'\cdot'+str(q)+r'^2=1,\qquad p_j+n_j\sqrt{'+L(d)+r'}=('+str(p)+'+'+str(q)+r'\sqrt{'+L(d)+r'})^j',r'n_j(p_j-n_j\sqrt{'+L(d)+r'})=\frac1{p_j/n_j+\sqrt{'+L(d)+r'}}\longrightarrow'+L(A),T('The Pell errors tend to zero, so the displayed integers are eventually the nearest ones. This attains the lower bound.')],'Pell-norm-sharp-liminf')

@register('limits','poisson-coefficient-limit','rare-event-generating-function-limit','uniform-log-product-and-coefficient-convergence','A coefficient of a growing product is controlled by a rare-event generating-function limit; repeated-index terms and the coefficient operation require justification.','The central-limit family studies fluctuations at square-root scale, whereas this uses bounded total event intensity.',[{'caseId':'power-'+str(a)+'-coefficient-'+str(j),'a':a,'j':j,'purpose':'Change the weight profile and the requested event count.'} for a,j in [(1,1),(1,3),(2,2),(2,4),(3,1),(3,3),(4,2),(4,4)]],['power series','uniform convergence on complex circles','coefficient extraction'])
def poisson(case):
 a=case['a'];j=case['j'];lam=R(1,a+1);A=s.exp(-lam)*lam**j/s.factorial(j)
 sumP=s.summation(k**a,(k,1,n))/n**(a+1)
 ck('The total intensity has the stated limit',s.limit(sumP,n,s.oo),lam)
 ck('The exact sum of squared probabilities vanishes',s.limit(s.summation(k**(2*a),(k,1,n))/n**(2*a+2),n,s.oo),0)
 ck('The limiting entire function has the requested coefficient',s.diff(s.exp(lam*(z-1)),z,j).subs(z,0)/s.factorial(j),A)
 analytic('Uniform generating-function convergence',['The coefficient index and positive integer weight power are fixed.','The expansion variable may lie on any fixed complex circle; for sufficiently large n every product perturbation has magnitude at most one half.'],['Write p_(n,k)=k^a/n^(a+1). Its maximum is1/n, its sum tends to lambda, and its squared sum tends to zero.','The uniform complex logarithm estimate log(1+w)=w+O(|w|^2) makes the product converge locally uniformly to exp(lambda(z-1)).','Cauchy coefficient integration on a fixed circle permits taking the coefficient limit. Differentiating the limiting exponential gives the Poisson coefficient.'])
 pool=[(lam**j/s.factorial(j),'Omit the probability of no additional events'),(s.exp(-lam)*lam**(j-1)/s.factorial(j-1),'Select one fewer event'),(s.exp(-lam)*lam**(j+1)/s.factorial(j+1),'Select one extra event'),(s.exp(-1)*lam**j/s.factorial(j),'Replace total intensity by one only in the exponential'),(s.exp(-lam)*lam**j/s.factorial(j+1),'Divide by the next factorial'),(s.exp(-lam)*lam**j/s.factorial(max(j-1,0)),'Forget a factor from unordered event selection')]
 return candidate(T('The bracket denotes the coefficient of the indicated power of z.')+r'\qquad\lim_{n\to\infty}[z^{'+str(j)+r'}]\prod_{k=1}^n\left(1+\frac{k^{'+str(a)+r'}}{n^{'+str(a+1)+r'}}(z-1)\right)',A,pool,[r'p_{n,k}=\frac{k^{'+str(a)+r'}}{n^{'+str(a+1)+r'}},\qquad\max_k p_{n,k}=\frac1n,\quad\sum_{k=1}^np_{n,k}\longrightarrow\lambda='+L(lam)+r',\quad\sum_{k=1}^np_{n,k}^2\longrightarrow0',T('On each fixed complex circle, the logarithm remainder is bounded by a constant times the squared perturbation. Summing it gives a remainder tending uniformly to zero.'),r'\prod_{k=1}^n(1+p_{n,k}(z-1))\longrightarrow e^{\lambda(z-1)}\quad\textnormal{locally uniformly in }z',T('Cauchy coefficient integration therefore passes this limit through the fixed coefficient extraction.'),r'[z^{'+str(j)+r'}]e^{\lambda(z-1)}=e^{-\lambda}\frac{\lambda^{'+str(j)+r'}}{'+str(j)+r'!}='+L(A)],'nonidentical-rare-event-product-coefficient')

@register('limits','binomial-large-deviation','entropy-rate-binomial-tail','dominant-term-tail-sandwich-and-Stirling','The tail is exponentially small, so a central-limit approximation is inappropriate; its largest term and entropy determine the root limit.','The Poisson group has bounded mean and the CLT group studies a moving threshold near the mean. Here the threshold remains a fixed fraction away.',[{'caseId':'p-'+str(p)+'-a-'+str(a),'p':str(p),'a':str(a),'purpose':'A fixed super-mean threshold with an exact integer subsequence.'} for p,a in [(R(1,2),R(2,3)),(R(1,3),R(1,2)),(R(1,4),R(1,2)),(R(1,3),R(2,3)),(R(1,5),R(2,5)),(R(2,5),R(3,5)),(R(1,4),R(3,4)),(R(2,3),R(3,4))]],['binomial coefficients','Stirling formula','exponential asymptotics'])
def large_deviation(case):
 p=R(case['p']);a=R(case['a']);den=int(a.q);num=int(a.p);A=(p/a)**a*((1-p)/(1-a))**(1-a)
 condition('The tail starts strictly above the mean',0<p<a<1,'Both parameters are fixed and strictly interior; the threshold exceeds p.')
 ck('The logarithmic entropy form equals the root expression',s.expand_log(s.log(A),force=True),a*s.log(p/a)+(1-a)*s.log((1-p)/(1-a)))
 ratio=(1-a)*p/(a*(1-p));condition('Successive tail terms are eventually decreasing',ratio<1,'The asymptotic ratio at the left tail endpoint is strictly below one.')
 analytic('Largest-term sandwich and factorial asymptotics',['The actual number of trials is the displayed denominator times the positive integer N, so the starting threshold is an integer.'],['Above the threshold, the binomial masses decrease for all sufficiently large indices. The entire tail lies between its first term and at most(n+1) times that term.','The nth root of the polynomial factor tends to one. Stirling applied to the three factorials in the first binomial coefficient gives a^(-a)(1-a)^(-(1-a)).','Multiplying the two probability weights yields the displayed positive rate below one.'])
 return candidate(r'p='+L(p)+r',\qquad B_N=\sum_{j='+str(num)+r'N}^{'+str(den)+r'N}\binom{'+str(den)+r'N}{j}p^j(1-p)^{'+str(den)+r'N-j}.\qquad\lim_{N\to\infty}B_N^{1/('+str(den)+r'N)}',A,[(A*A,'Use twice the correct logarithmic rate'),(s.sqrt(A),'Use half the correct logarithmic rate'),(A**3,'Use three times the correct logarithmic rate'),(A**R(1,3),'Use one third of the correct logarithmic rate'),(p**a*(1-p)**(1-a),'Omit the entropy contribution of the binomial coefficient'),(s.Integer(1),'Assume every probability tail is subexponential')],[r'n='+str(den)+r'N,\quad a='+L(a)+r'>p,\qquad t_j=\binom njp^j(1-p)^{n-j}',r'\frac{t_{j+1}}{t_j}=\frac{n-j}{j+1}\frac p{1-p}<1\quad\textnormal{for }j\ge an\textnormal{ and large }n',r't_{an}\le B_N\le(n+1)t_{an}',r'\binom n{an}^{1/n}\longrightarrow\frac1{a^a(1-a)^{1-a}}\quad\textnormal{by Stirling}',r'B_N^{1/n}\longrightarrow\left(\frac pa\right)^a\left(\frac{1-p}{1-a}\right)^{1-a}='+L(A)],'fixed-fraction-binomial-large-deviation-tail')

@register('limits','nilpotent-matrix-asymptotics','Jordan-chain-polynomial-growth','nilpotent-binomial-expansion','The exponential rate alone is insufficient: the last nonzero nilpotent power determines the polynomial normalization and the selected matrix entry.','The Hankel family cancels two scalar modes. This family extracts a Jordan chain of a non-diagonalizable matrix.',[{'caseId':'chain-'+str(r)+'-shear-'+str(h),'r':r,'h':h,'lam':lam,'purpose':'Distinct nilpotent chain lengths and basis shears.'} for r,h,lam in [(3,1,2),(3,2,3),(3,-1,2),(3,-2,4),(4,1,2),(4,2,3),(4,-1,2),(4,-2,4)]],['matrix multiplication','binomial theorem','nilpotent operators'])
def jordan(case):
 r=case['r'];h=case['h'];lam=s.Integer(case['lam']);J=s.zeros(r)
 for j in range(r-1):J[j,j+1]=1
 S=s.eye(r);S[r-1,0]=h;S[1,0]=h+1
 A=S*(lam*s.eye(r)+J)*S.inv();N=A-lam*s.eye(r);row=r-1;col=r-1;lead=(S*J**(r-1)*S.inv())[row,col]
 condition('The selected entry sees the longest chain',lead!=0,'The entry of the last nonzero nilpotent power is nonzero.')
 ans=lead/(s.factorial(r-1)*lam**(r-1))
 ck('The shifted matrix has the asserted nilpotence order',N**r,s.zeros(r));ck('The leading coefficient is independent of the construction basis',(N**(r-1))[row,col],lead)
 for j in [r,r+2]:ck('Direct power agrees with the truncated binomial expansion at '+str(j),A**j,sum((s.binomial(j,k)*lam**(j-k)*N**k for k in range(r)),s.zeros(r)))
 analytic('Finite nilpotent expansion',['The fixed positive eigenvalue is nonzero, the shifted matrix has exact nilpotence order equal to the displayed dimension, and the selected leading entry is nonzero.'],['The commuting decomposition A=lambda I+N gives an exact finite binomial expansion. Divide each entry by lambda^n n^(r-1).','Terms below the last nonzero power vanish. The final binomial coefficient divided by n^(r-1) tends to1/(r-1)!; the additional lambda power remains in the denominator.'])
 return candidate(r'A='+L(A)+r'.\qquad\lim_{n\to\infty}\frac{(A^n)_{'+str(r)+','+str(r)+r'}}{'+L(lam)+r'^n n^{'+str(r-1)+r'}}',ans,[(lead/lam**(r-1),'Omit the leading factorial'),(lead/s.factorial(r-1),'Omit the eigenvalue power'),(lead/(s.factorial(r-1)*lam**r),'Use one extra eigenvalue factor'),(lead/(s.factorial(r)*lam**(r-1)),'Use the dimension factorial instead of the chain-degree factorial'),(-ans,'Reverse the sign of the last nilpotent entry'),(ans*lam,'Drop one eigenvalue factor')],[T('Write I for the identity matrix and subtract the scalar eigenvalue.'),r'N=A-'+L(lam)+r'I,\qquad N^{'+str(r)+r'}=0,\quad(N^{'+str(r-1)+r'})_{'+str(r)+','+str(r)+'}='+L(lead),r'A^n=\sum_{j=0}^{'+str(r-1)+r'}\binom nj'+L(lam)+r'^{n-j}N^j',T('After normalization, every lower power vanishes. The last binomial coefficient contributes its leading polynomial coefficient.'),r'\frac{\binom n{'+str(r-1)+r'}}{n^{'+str(r-1)+r'}}\longrightarrow\frac1{'+str(r-1)+r'!}',r'\lim_{n\to\infty}\frac{(A^n)_{'+str(r)+','+str(r)+r'}}{'+L(lam)+r'^n n^{'+str(r-1)+r'}}=\frac{'+L(lead)+'}{'+str(r-1)+r'!\,'+L(lam)+r'^{'+str(r-1)+'}}='+L(ans)],'nondiagonalizable-matrix-longest-chain-entry')

@register('limits','divisor-hyperbola-constant','divisor-summatory-hyperbola','hyperbola-decomposition-and-harmonic-asymptotic','Accumulated floor errors are too large for a naive termwise approximation; an exact hyperbola split reduces the error to a square-root boundary.','Single floor bounds and ordinary fixed-interval Riemann sums do not resolve the second-order constant.',[{'caseId':'omit-'+str(a),'a':a,'purpose':'Keep track of a different finite omitted block, including the empty block.'} for a in range(8)],['floor function','harmonic sums','counting lattice points'])
def hyperbola(case):
 a=case['a'];H=s.harmonic(a);g=s.EulerGamma;A=2*g-1-H
 for N in [15,16,17,80,81,82]:
  M=math.isqrt(N);ck('Exact hyperbola count at '+str(N),sum(N//j for j in range(1,N+1)),2*sum(N//j for j in range(1,M+1))-M*M)
 analytic('Dirichlet hyperbola identity',['The limit variable is a positive integer and the omitted initial block has fixed size. The Euler constant is defined in the statement.'],['The divisor sum counts positive lattice pairs with product at most n. Every such pair has at least one coordinate at most floor(sqrt(n)); count the two arms and subtract the square intersection.','Replace only the floor terms in each short arm by n/j; their total error is O(sqrt(n)). The harmonic expansion H_M=ln M+gamma+o(1), M/sqrt(n)->1, gives n ln n+(2gamma-1)n+o(n).','Each of the finitely many omitted terms floor(n/j)/n tends to1/j.'])
 return candidate(r'\gamma=\lim_{q\to\infty}\left(\sum_{j=1}^q\frac1j-\ln q\right).\qquad\lim_{n\to\infty}\frac{\displaystyle\sum_{k='+str(a+1)+r'}^n\left\lfloor\frac nk\right\rfloor-n\ln n}{n}',A,[(g-1-H,'Count only one arm of the hyperbola'),(2*g-H,'Forget the overlap square'),(2*g-2-H,'Subtract the overlap twice'),(2*g-1-H/2,'Remove only half the omitted block'),(2*g-1-s.harmonic(a+1),'Omit one additional initial term'),(2*g-1-2*H,'Subtract the initial block twice')],[r'D_n=\sum_{k=1}^n\left\lfloor\frac nk\right\rfloor,\quad M=\lfloor\sqrt n\rfloor,\qquad D_n=2\sum_{k=1}^M\left\lfloor\frac nk\right\rfloor-M^2',T('The two short arms count every lattice pair, and their square intersection is counted twice before subtraction.'),r'H_M=\sum_{j=1}^M\frac1j,\qquad D_n=2nH_M-M^2+O(M),\quad H_M=\ln M+\gamma+o(1)',r'\frac{D_n-n\ln n}{n}\longrightarrow2\gamma-1',r'\frac1n\sum_{k=1}^{'+str(a)+r'}\left\lfloor\frac nk\right\rfloor\longrightarrow\sum_{k=1}^{'+str(a)+r'}\frac1k='+L(H),r'\textnormal{The requested limit is }2\gamma-1-'+L(H)+'='+L(A)],'renormalized-floor-sum-moving-hyperbola-cutoff')

